# >>> CHOICES
_choice_types() {
    local dir=$PWD name
    while :; do
        if [[ -d $dir/node_modules/@types ]]; then
            for name in "$dir"/node_modules/@types/*/; do
                [[ -d $name ]] || continue
                name=${name%/}
                printf '%s\n' "${name##*/}"
            done
            return 0
        fi
        [[ $dir == / ]] && return 0
        dir=${dir%/*}
        [[ -n $dir ]] || dir=/
    done
}
